import ast,base64,contextlib,gzip,hashlib,io,json,os,pathlib,shutil,stat,sys,traceback
def decode(value):return base64.urlsafe_b64decode(value+'='*((4-len(value)%4)%4))
native_source=decode('-').decode()
qualifier_source=decode('').decode()
carrier_source=decode('').decode()
assert hashlib.sha256(native_source.encode()).hexdigest()=='090e5f030e10e8f318f7c0052670321c8992a9fea6caa66607c4ca6517d4fc68'
assert hashlib.sha256(qualifier_source.encode()).hexdigest()=='e818826150edfb41650d23a7f41d9485fb0330e8442a5a9340d0ac98ab9bdce9'
assert hashlib.sha256(carrier_source.encode()).hexdigest()=='18508b5c566d13c7d6f4a4ec680f2d34c84d12fcc741f38a466b4679aeea66b9'
for source in (native_source,qualifier_source,carrier_source):ast.parse(source)
if len(sys.argv)>2:raise SystemExit('Usage: native-source-receiving.py [PRIVATE_REQUEST_JSON]')
if len(sys.argv)==2:
 with pathlib.Path(sys.argv[1]).open() as handle:request=json.load(handle)
else:request=json.load(sys.stdin)
required={'archiveTransfers','upload','attemptLabel'}
if not required.issubset(request) or set(request)-required-{'followingPreparation'} not in ({'qualificationTransfer'},{'residualSourcePacket'}):raise ValueError('Use original source transfers and upload with exactly one selected original source intake')
attempt_label=request['attemptLabel']
if not isinstance(attempt_label,str) or not attempt_label.startswith('native-') or not attempt_label[7:].isdigit() or int(attempt_label[7:])<3:raise ValueError('Use the selected numbered continuation of the original native operation')
operation='SCF-STAC-MANAGED-APPLICATION-RECEIVING-B710-20261012'
root=pathlib.Path('/dev/b710-stac-applications-7169');root.mkdir(mode=0o700,parents=True,exist_ok=True)
info=root.lstat()
assert stat.S_ISDIR(info.st_mode) and not root.is_symlink() and info.st_uid==os.getuid() and info.st_mode&0o077==0
# Create the required private parent itself before any nested retained source.
delivery=root/'delivery';delivery.mkdir(mode=0o700,exist_ok=True)
delivery_info=delivery.lstat()
if not stat.S_ISDIR(delivery_info.st_mode) or delivery.is_symlink() or delivery_info.st_uid!=os.getuid() or delivery_info.st_mode&0o077:raise ValueError('Preserve a non-private original delivery directory: '+str(delivery))
def exact(path,data):
 path.parent.mkdir(mode=0o700,parents=True,exist_ok=True)
 if path.exists():
  assert not path.is_symlink() and path.read_bytes()==data,str(path)
 else:
  with path.open('xb') as handle:handle.write(data)
 path.chmod(0o600)
private_native={k:request[k] for k in ['archiveTransfers','upload','attemptLabel']}
if 'followingPreparation' in request:private_native['followingPreparation']=request['followingPreparation']
private_path=root/'private-uploads'/(attempt_label+'-request.json')
exact(private_path,(json.dumps(private_native)+'\n').encode())
if 'qualificationTransfer' in request:exact(root/'private-uploads'/(attempt_label+'-qualification-request.json'),(json.dumps({'transfer':request['qualificationTransfer']})+'\n').encode())
else:exact(root/'private-uploads'/(attempt_label+'-source-packet-request.json'),(json.dumps(request['residualSourcePacket'])+'\n').encode())
exact(root/'delivery'/'original-operation'/'native-receiving.py',native_source.encode())
exact(root/'delivery'/'original-operation'/'qualify-completed-source.py',qualifier_source.encode())
print(json.dumps({'stage':'ORIGINAL_NATIVE_SOURCE_INTAKE','sourceInput':'complete-residual-packet' if 'residualSourcePacket' in request else 'existing-library-archive','operationId':operation,'attemptLabel':attempt_label,'root':str(root),'pid':os.getpid(),'nativeSourceSha256':hashlib.sha256(native_source.encode()).hexdigest(),'qualifierSourceSha256':hashlib.sha256(qualifier_source.encode()).hexdigest(),'azcopyOnPath':shutil.which('azcopy')}),flush=True)
def original_carrier():
 os.environ['OPENFEMA_RECEIVING_ROOT']=str(root)
 os.environ['OPENFEMA_OPERATION_ID']=operation
 sys.stdin=sys.__stdin__
 exec(compile(carrier_source,'original-retained-carrier.py','exec'),{'__name__':'__main__'})

def retain_failure(stage,error):
 diagnostic=root/'private-uploads'/(stage.lower()+'-failure.txt')
 try:
  with diagnostic.open('x') as output:output.write(traceback.format_exc())
  diagnostic.chmod(0o600)
 except OSError:pass
 print(json.dumps({'stage':stage,'operationId':operation,'attemptLabel':attempt_label,'errorType':type(error).__name__,'exitCode':error.code if isinstance(error,SystemExit) and isinstance(error.code,int) else None,'privateDiagnostic':str(diagnostic),'root':str(root)}),flush=True)

def stage_blob(oid,data):
 incoming=root/'operation-base'/'incoming'
 incoming.mkdir(mode=0o700,parents=True,exist_ok=True)
 target=incoming/(oid+'.blob')
 if target.exists():
  if target.is_symlink() or target.read_bytes()!=data:raise ValueError('Preserve a changed original incoming object: '+oid)
  return
 pending=incoming/(oid+'.receiving')
 if pending.exists():
  if pending.is_symlink() or pending.read_bytes()!=data:raise ValueError('Preserve a changed pending source object: '+oid)
 else:
  with pending.open('xb') as output:
   output.write(data)
   output.flush()
   os.fsync(output.fileno())
  pending.chmod(0o600)
 os.link(pending,target)
 pending.unlink()

def complete_residual_packet(selection):
 expected={
  'bytes':2468401,
  'sha256':'4ab15fe3bdcd26648a896a251fcaaec41d6e4577c188f4412ba0ead3bcb50ea9',
  'gzipBytes':1851298,
  'gzipSha256':'82cb77166ab6f9e53efa748009ca3ff297bb2533691cd2760f1f2d34f6bd588e',
  'decodedBytes':7127758,
  'decodedSha256':'eb133b97b3e7bb24ef10eef5aa45d7a45aefffa05062836ed6d6831a8b2d1bfc'
 }
 if not isinstance(selection,dict) or set(selection)!={'path',*expected}:raise ValueError('Use the complete selected source packet and exact identities')
 for key,value in expected.items():
  if selection[key]!=value:raise ValueError('The original residual source packet selection changed: '+key)
 source=pathlib.Path(selection['path'])
 if not source.is_absolute() or source.is_symlink() or not source.is_file():raise ValueError('Use the original absolute source-packet file')
 encoded=source.read_bytes()
 if len(encoded)!=expected['bytes'] or hashlib.sha256(encoded).hexdigest()!=expected['sha256']:raise ValueError('Complete encoded source packet changed')
 if not encoded.endswith(b'\n') or b'\n' in encoded[:-1] or b'\r' in encoded:raise ValueError('Preserve the complete source packet encoding')
 compressed=base64.b64decode(encoded[:-1],validate=True)
 if len(compressed)!=expected['gzipBytes'] or hashlib.sha256(compressed).hexdigest()!=expected['gzipSha256']:raise ValueError('Compressed original source packet changed')
 raw=gzip.decompress(compressed)
 if len(raw)!=expected['decodedBytes'] or hashlib.sha256(raw).hexdigest()!=expected['decodedSha256']:raise ValueError('Decoded original source packet changed')
 packet=json.loads(raw)
 if packet.get('format')!='commons-git-blob-source-packet-v1' or packet.get('operationId')!=operation:raise ValueError('Use the original source operation')
 metadata=packet['missingMetadata']['content'].encode('utf-8')
 metadata_sha=hashlib.sha256(metadata).hexdigest()
 if len(metadata)!=71756 or packet['missingMetadata']['bytes']!=71756 or metadata_sha!='b2c56fbccf5b58e7de48592c30ea2bcf367d8a716d864a38ed6c6566265e92d6' or packet['missingMetadata']['sha256']!=metadata_sha:raise ValueError('The retained original residual metadata changed')
 residual=json.loads(metadata)
 if packet['source']!=residual['source'] or residual['source']!={'commit':'7169c10e37a1800d22133efaf37cfaac5d96e343','repository':'https://github.com/woahwhattheheck/public-commons-sprint-2026','tree':'eda6ec9050eeedb4bd401c66b7bfba0b604a8fca'}:raise ValueError('The fixed complete source selection changed')
 objects=packet['objects']
 if packet['objectCount']!=467 or len(objects)!=467 or len(residual['objects'])!=467 or packet['objectBytes']!=6836872:raise ValueError('Use every original residual object')
 seen=set();total=0
 for wanted,item in zip(residual['objects'],objects):
  oid=item['sha']
  if oid in seen or oid!=wanted['sha'] or item['size']!=wanted['size'] or not isinstance(item.get('content'),str):raise ValueError('Original source object identity or order changed')
  seen.add(oid)
  data=item['content'].encode('utf-8')
  if len(data)!=wanted['size'] or hashlib.sha256(data).hexdigest()!=item['sha256'] or hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()!=oid:raise ValueError('Original source object bytes changed: '+oid)
  total+=len(data)
 if total!=6836872:raise ValueError('The complete raw source extent changed')
 retained_packet=root/'delivery'/'original-source'/'fixed7169-residual-source.json.gz.b64'
 exact(retained_packet,encoded)
 exact(root/'delivery'/'original-source'/'native-02-missing-objects.json',metadata)
 for item in objects:stage_blob(item['sha'],item['content'].encode('utf-8'))
 result={
  'schema':'commons.stac-original-source-intake.v1',
  'operationId':operation,
  'attemptLabel':attempt_label,
  'source':residual['source'],
  'sourcePacket':{**expected,'path':str(retained_packet)},
  'missingMetadata':{'bytes':len(metadata),'sha256':metadata_sha},
  'matchedObjects':len(objects),
  'matchedBytes':total,
  'remainingObjects':0,
  'incoming':str(root/'operation-base'/'incoming')
 }
 body=(json.dumps(result,indent=2)+'\n').encode()
 exact(root/'delivery'/('source-intake-'+attempt_label+'.json'),body)
 print(json.dumps({'stage':'ORIGINAL_COMPLETE_SOURCE_PACKET_JOINED',**result}),flush=True)
 return result

def existing_archive_qualification():
 qualifier_namespace={'__name__':'__main__'}
 qualifier_log=root/('source-qualification-'+attempt_label+'.stdout')
 sys.stdin=io.StringIO(json.dumps({'transfer':request['qualificationTransfer']})+'\n')
 with qualifier_log.open('x') as output,contextlib.redirect_stdout(output):
  exec(compile(qualifier_source,'qualify-completed-source.py','exec'),qualifier_namespace)
 qualifier_log.chmod(0o600)
 sys.stdin=sys.__stdin__
 result=qualifier_namespace.get('result')
 if result is None:
  print(json.dumps({'stage':'QUALIFICATION_ATTENTION','operationId':operation,'attemptLabel':attempt_label,'qualifierRoot':str(qualifier_namespace.get('root')),'originalLog':str(qualifier_log)}),flush=True)
  return None
 residual=pathlib.Path('/dev/shm/b710-stac-managed-applications-native-delivery/native-02-missing-objects.json').read_bytes()
 if hashlib.sha256(residual).hexdigest()!='b2c56fbccf5b58e7de48592c30ea2bcf367d8a716d864a38ed6c6566265e92d6':raise ValueError('The original source residual changed')
 residual_rows={r['sha']:r for r in json.loads(residual)['objects']}
 source_root=pathlib.Path(qualifier_namespace['root'])
 for hit in result['matched']['files']:
  oid=hit['sha']
  if len(oid)!=40 or any(c not in '0123456789abcdef' for c in oid) or oid not in residual_rows:raise ValueError('An archive match is outside the original residual')
  data=(source_root/'matched'/oid).read_bytes()
  if len(data)!=hit['bytes'] or len(data)!=residual_rows[oid]['size'] or hashlib.sha256(data).hexdigest()!=hit['sha256'] or hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()!=oid:raise ValueError('Original archive match changed')
  stage_blob(oid,data)
 qualification=(source_root/'source-donor-qualification.json').read_bytes()
 exact(root/'delivery'/('source-donor-qualification-'+attempt_label+'.json'),qualification)
 exact(root/'delivery'/('source-qualification-'+attempt_label+'.stdout'),qualifier_log.read_bytes())
 print(json.dumps({'stage':'ORIGINAL_SOURCE_DONOR_JOINED','operationId':operation,'attemptLabel':attempt_label,'archive':result['archive'],'matchedObjects':result['matched']['objects'],'matchedBytes':result['matched']['bytes'],'remaining':result['remaining'],'incoming':str(root/'operation-base'/'incoming'),'qualificationBytes':len(qualification),'qualificationSha256':hashlib.sha256(qualification).hexdigest()}),flush=True)
 try:exact(pathlib.Path('/dev/shm/b710-stac-managed-applications-native-delivery')/(attempt_label+'-source-donor-qualification.json'),qualification)
 except OSError as error:print(json.dumps({'stage':'QUALIFICATION_SHARED_SAVE','errorType':type(error).__name__,'errno':error.errno}),flush=True)
 return result

ready=False
try:
 result=complete_residual_packet(request['residualSourcePacket']) if 'residualSourcePacket' in request else existing_archive_qualification()
 if result is not None:
  prior=pathlib.Path('/dev/shm/b710-stac-managed-applications-native-delivery')
  for name in ['native-02-NATIVE_OPERATION.json','native-02-transfer-native-02.json','native-02-one-allocation-result.json','native-02-native-continuation-exit.json','native-02-source-receiving.json','native-02-missing-objects.json']:
   path=prior/name
   if path.is_file():exact(root/'delivery'/'history'/'native-02'/name,path.read_bytes())
  ready=True
except Exception as error:retain_failure('ORIGINAL_SOURCE_INTAKE_ATTENTION',error)
if not ready:
 original_carrier()
else:
 sys.argv=['native-receiving.py',str(private_path)]
 try:
  exec(compile(native_source,'native-receiving.py','exec'),{'__name__':'__main__'})
 except (Exception,SystemExit) as error:
  if isinstance(error,SystemExit) and error.code in (None,0):raise
  retain_failure('ORIGINAL_NATIVE_PREPARATION_ATTENTION',error)
